import socket,subprocess,json,pathlib,hashlib,os,base64,zlib
R=pathlib.Path('/home/jovyan/shares/SR003.nfs2/GENATATOR_PIPELINE/diploma_yandex_graphs')
UUID='GPU-44039938-fd82-41d2-fefd-de71514e2fac'
assert socket.gethostname()=='anogena-2-0'
assert subprocess.check_output(['nvidia-smi','--query-gpu=uuid','--format=csv,noheader'],text=True,timeout=15).splitlines()==[UUID]
os.chdir(R)
payload=json.loads(zlib.decompress(base64.b64decode('')))
phase=R/'experiments_iclr/postsubmission_20260930'
source=phase/'Physics_original_boundary_GNNM_anchor_source_20261011_v1'
H=phase/'Physics_original_boundary_GNNM_anchor_readiness_execution_20261011_v1'
def receipt(p):
 p=pathlib.Path(p).resolve();h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1048576),b''):h.update(b)
 return dict(path=str(p),bytes=p.stat().st_size,sha256=h.hexdigest())
def write(p,value):
 with p.open('x') as f:f.write(json.dumps(value,indent=2)+'\n')
H.mkdir(exist_ok=False)
if source.exists():
 for name,value in payload['source_bundle'].items():
  assert (source/name).read_bytes()==base64.b64decode(value),'Existing sealed source differs'
else:
 source.mkdir()
 for name,value in payload['source_bundle'].items():
  with (source/name).open('xb') as f:f.write(base64.b64decode(value))
assert receipt(source/'MANIFEST.json')['sha256']==payload['source_manifest_sha256']
m=json.loads((source/'MANIFEST.json').read_text())
for row in m['files']:
 r=receipt(source/row['path']);assert r['bytes']==row['bytes'] and r['sha256']==row['sha256']
deps=H/'dependencies';deps.mkdir()
with (deps/'original_comparator.py').open('xb') as f:f.write(base64.b64decode(payload['helper']))
for name in ['worker.py','owner.py']:
 with (H/name).open('x') as f:f.write(payload[name])
runtime={}
for name,fixed in payload['bindings']['runtime_sources'].items():
 if name=='native_models':path=R/'models.py'
 elif name=='native_common':path=R/'run_common.py'
 elif name=='original_comparator':path=deps/'original_comparator.py'
 elif name in ['native_sage_conv','native_message_passing']:path=pathlib.Path(fixed['path'])
 else:
  suffix=pathlib.Path(fixed['path']).parts
  marker=suffix.index('postsubmission_research_20260930')
  path=phase/pathlib.Path(*suffix[marker+1:])
 got=receipt(path);assert got['bytes']==fixed['bytes'] and got['sha256']==fixed['sha256'],name
 runtime[name]=got
metadata=receipt(phase/'native_SAGE_Physics_confirmation_root_20261011_v1/FROZEN_BINDINGS_V1.json')
assert metadata['sha256']==payload['physics_metadata_sha256']
frozen=json.loads(pathlib.Path(metadata['path']).read_text())
role_map={r['path']:r for r in frozen['bound_files']}
roles=payload['bindings']['Physics_roles']
for block,rr in roles.items():
 for role,r in rr.items():
  assert role_map[r['path']]==r
actual_train=receipt(roles['8101']['train']['path']);assert actual_train==roles['8101']['train']
python=R/'.venv/bin/python';assert python.is_file() and os.access(python,os.X_OK)
source_sha={str(source/name):receipt(source/name)['sha256'] for name in ['acquire.py','PLAN.json','INTERFACE.json','SOURCE_BINDINGS.json']}
limits=dict(wall_seconds=600,cuda_bytes=48*1024**3,rss_bytes=64*1024**3)
decision=dict(status='ROOT_READINESS_ONLY_ADMITTED',authority='Explicit root instruction for exactly one Physics original-boundary full-input readiness action',
 action='Physics_original_boundary_readiness',limits=limits,external_owner_wall_seconds=660,
 source_directory=str(source),source_sha256=source_sha,source_manifest=receipt(source/'MANIFEST.json'),
 existing_Physics_metadata_binding=metadata,verified_runtime_sources=runtime,verified_TRAIN_receipt=actual_train,
 runtime_executable=str(python),owner_source=receipt(H/'owner.py'),worker_source=receipt(H/'worker.py'),
 allowed_work='One block8101 full-graph TRAIN update plus strict model/optimizer/Python/NumPy/CPU/CUDA RNG restoration',
 SELECT_array_or_forward=False,CAL_TEST_access=False,full_scientific_acquisition_admitted=False,
 no_retry=True,representative_execution_risk_only=True,scientific_quality_or_novelty_evidence=False)
write(H/'ROOT_DECISION.json',decision)
spec=dict(output=str(H/'readiness_v1'),limits=limits,decision=receipt(H/'ROOT_DECISION.json'),
 source_receipts=runtime,roles=roles)
write(H/'SPEC.json',spec)
write(H/'PREPARATION_RECEIPT.json',dict(hostname=socket.gethostname(),GPU_UUID=UUID,
 source_manifest=receipt(source/'MANIFEST.json'),runtime_sources=runtime,
 existing_Physics_metadata_binding=metadata,TRAIN_receipt=actual_train,
 source_deployed_exact=True,SELECT_CAL_TEST_arrays_deserialized=False,
 decision=receipt(H/'ROOT_DECISION.json'),spec=receipt(H/'SPEC.json')))
print(json.dumps(dict(status='DEPLOYED_AND_METADATA_BOUND',source_manifest_sha256=payload['source_manifest_sha256'],
 action=decision['action'],execution_directory=str(H),limits=limits)),flush=True)
code=subprocess.call([str(python),'-B','-u',str(H/'owner.py')],cwd=R)
raise SystemExit(code)
